mapper.update:
update biz_contract
contract_name=#{contract.contractName}, customer_id=#{contract.customerId}, customer_name=#{contract.customerName}, case_type=#{contract.caseType}, lawyer_id=#{contract.lawyerId}, lawyer_name=#{contract.lawyerName}, owner_id=#{contract.ownerId}, dept_id=#{contract.deptId}, sign_amount=#{contract.signAmount}, fee_type=#{contract.feeType}, sign_date=#{contract.signDate}, effective_date=#{contract.effectiveDate}, expire_date=#{contract.expireDate}, sign_method=#{contract.signMethod}, risk_level=#{contract.riskLevel}, remark=#{contract.remark}, update_by=#{contract.updateBy}, update_time=sysdate()
where contract_id=#{contract.contractId} and audit_status=#{expectedAuditStatus} and contract_status=#{expectedContractStatus} and del_flag=#{expectedDelFlag}

update biz_contract
set del_flag='2', update_by=#{updateBy}, update_time=sysdate()
where contract_id=#{contractId}
  and audit_status=#{expectedAuditStatus}
  and contract_status=#{expectedContractStatus}
  and del_flag='0'

update biz_contract
set audit_status=#{auditStatus}, contract_status=#{contractStatus}, update_by=#{updateBy}, update_time=sysdate()
where contract_id=#{contractId}
and del_flag='0'
and audit_status=#{expectedAuditStatus}
and contract_status=#{expectedContractStatus}

