and audit_status=#{expectedAuditStatus}
and contract_status=#{expectedContractStatus}

mapper.select:
select p.*, c.contract_no contractNo,c.contract_name contractName,c.customer_name customerName,c.contract_status contractStatus from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id

    and p.contract_id=#{contractId}
    and (c.contract_no like concat('%',#{keyword},'%') or c.contract_name like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%'))
    and p.confirm_status=#{confirmStatus}
    and p.invoice_status=#{invoiceStatus}
    and c.del_flag='0'


order by p.contract_id desc,p.period_no

mapper.delete:
delete from biz_contract_fee_plan
where plan_id=#{planId}
and confirm_status=#{expectedConfirmStatus}
and invoice_status=#{expectedInvoiceStatus}
and exists (
    select 1 from biz_contract c
    where c.contract_id = biz_contract_fee_plan.contract_id
    and c.del_flag = '0'
    and c.contract_status = #{expectedContractStatus}
)

delete from biz_contract_attachment
where attachment_id=#{attachmentId}
  and contract_id=#{contractId}
  and exists (
      select 1 from biz_contract c
      where c.contract_id=#{contractId}
        and c.del_flag='0'
        and c.contract_status=#{expectedContractStatus}
  )
